<script setup>
import {formatUnixTime} from '../../shared/datePresentation.js'

import {computed,ref,watch} from 'vue'


import DateRangeFilter from '../../shared/components/DateRangeFilter.vue'
import {useTableLayout} from '../../shared/composables/tableLayout.js'
import {resourceTitles,filterCatalog,auditActionLabel,auditResourceLabel} from '../resourceCatalog.js'
import {resourceKindLabels,connectionDatabaseLabel} from '../resourceConnections.js'
const props=defineProps({kind:String,items:{type:Array,default:()=>[]},environments:{type:Array,default:()=>[]},connectionKinds:{type:Array,default:()=>[]},loading:Boolean,error:String,showAgents:Boolean,pending:{type:Object,default:()=>({})},testState:{type:Object,default:()=>({})},agentState:Function})
const emit=defineEmits(['create','edit','remove','test','agent-config','agent-check','agent-install','refresh','navigate'])
const {pinTableActions}=useTableLayout()
const query=ref(''),filter=ref(''),start=ref(''),end=ref(''),page=ref(1)
const filtered=computed(()=>filterCatalog(props.kind,props.items,{query:query.value,filter:filter.value,start:start.value,end:end.value},props.environments))
const rows=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20))
watch([query,filter,start,end],()=>page.value=1)
watch(()=>filtered.value.length,n=>page.value=Math.min(page.value,Math.max(1,Math.ceil(n/20))))
const options=computed(()=>props.kind==='connections'?props.connectionKinds:props.kind==='audit'?[...new Set(props.items.map(r=>r.resource_type))].filter(Boolean).map(value=>({value,label:auditResourceLabel(value)})):props.environments.map(env=>({value:env.name,label:env.display_name||env.name})))
const fmt=formatUnixTime
const env=value=>props.environments.find(e=>e.name===value)?.display_name||value||'—'
const columns=computed(()=>({
 connections:[['name','连接名称',220],['kind','类型',170],['endpoint','地址 / 实例',280],['database','选库 / DB',160],['credentials','凭据',120]],
 hosts:[['name','主机名称',180],['environment','所属环境',140],['addr','地址',200],['user','SSH 用户',120],['credentials','凭据',130],['connectivity','连通性',120],...(props.showAgents?[['agent','采集 Agent',160]]:[])],
 groups:[['name','主机组',200],['environment','所属环境',140],['hosts','包含主机',300],['description','说明',260]],
 variables:[['name','变量组',200],['description','说明',250],['keys','变量键',280],['updated_at','更新时间',190]],
 audit:[['created_at','时间',190],['actor','操作者',160],['action','操作',230],['resource_type','资源类型',180],['resource_id','资源标识',260]]
})[props.kind]||[])
const actionWidth=computed(()=>props.kind==='hosts'&&props.showAgents?310:props.kind==='connections'||props.kind==='hosts'?220:150)
const scrollWidth=computed(()=>columns.value.reduce((sum,c)=>sum+c[2],0)+(props.kind==='audit'?0:actionWidth.value))
function clear(){query.value='';filter.value='';start.value='';end.value=''}
const busy=row=>props.loading||!!props.pending[row.name]||props.testState[row.name]==='testing'
const createLabel=computed(()=>({connections:'新建连接',hosts:'新增主机',groups:'新建主机组',variables:'新建变量组'})[props.kind])

import OptionPicker from '../../shared/components/OptionPicker.vue'

import {PlusIcon as IconPlus,SearchIcon as IconSearch,RefreshCwIcon as IconRefresh} from '@lucide/vue'


import {Badge,Button,DropdownMenu,DropdownMenuContent,DropdownMenuItem,DropdownMenuTrigger,Empty,EmptyContent,EmptyDescription,EmptyHeader,EmptyTitle,Input,Pagination,PaginationContent,PaginationNext,PaginationPrevious,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
</script>
<template><section :aria-label="resourceTitles[kind]+'管理'"><div class="catalog-heading"><h3>{{resourceTitles[kind]}}</h3><div class="catalog-actions"><Button v-if="kind==='groups'" @click="emit('navigate','hosts')" variant="outline" size="default" type="button">管理主机</Button><Button v-if="kind!=='audit'" @click="emit('create')" variant="default" size="default" type="button" :disabled="(loading||!!error)"><IconPlus/>{{createLabel}}</Button></div></div><div class="catalog-toolbar"><InputGroup  class="min-w-0 "><InputGroupInput v-model="query" :placeholder="kind==='audit'?'搜索操作者、操作或资源标识':kind==='variables'?'搜索名称、说明或变量键':'搜索名称、地址或资源'" v-bind="{'aria-label':'搜索'+resourceTitles[kind]}"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="query" :disabled="false" size="icon-xs" aria-label="清空输入" @click="query='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><OptionPicker v-if="kind!=='variables'" v-model="filter" :style="{width:'180px'}" :aria-label="resourceTitles[kind]+'分类筛选'" :options="[{value:&quot;&quot;,label:String(kind==='connections'?'全部类型':kind==='audit'?'全部资源类型':'全部环境')},...(options).map((o)=>({value:o.value,label:String(o.label)}))]"/><DateRangeFilter v-if="kind==='audit'" v-model:start="start" v-model:end="end" width="340px" label="时间"/><Button :aria-label="'重新加载'+resourceTitles[kind]" @click="emit('refresh')" class="catalog-refresh" variant="outline" size="default" type="button" :disabled="(loading)"><Spinner v-if="loading"/><IconRefresh/></Button></div><Empty v-if="error"><EmptyHeader><EmptyTitle>{{resourceTitles[kind]+'加载失败'}}</EmptyTitle><EmptyDescription>{{error}}</EmptyDescription></EmptyHeader><EmptyContent><Button @click="emit('refresh')" variant="default" size="default" type="button">重新加载</Button></EmptyContent></Empty><template v-else><div class="console-table min-w-0 max-w-full"><div v-if="loading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:scrollWidth}).y?({x:scrollWidth}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:scrollWidth}).x||({x:scrollWidth}).minWidth||300)+'px'}"><TableHeader class="bg-muted/50"><TableRow><TableHead v-for="[key,title,width] in columns" :key="key" :style="{width:(width)+'px'}">{{title}}</TableHead><TableHead v-if="kind!=='audit'" :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-muted':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-muted':''" :style="{width:(actionWidth)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (rows||[])" :key="typeof (kind==='audit'?'id':'name')==='function'?(kind==='audit'?'id':'name')(record):record[kind==='audit'?'id':'name']??rowIndex"><TableRow><TableCell v-for="[key,title,width] in columns" :key="key" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(!['hosts','keys','agent','database'].includes(key))}"><template v-for="{record:r} in [{record,rowIndex}]"><b v-if="key==='name'">{{r.name}}</b><template v-else-if="key==='kind'">{{resourceKindLabels[r.kind]||r.kind}}</template><code v-else-if="key==='endpoint'">{{r.kind==='aliyun-sae'?`${r.config?.region||'—'} · ${r.config?.oss_bucket||'未配置 OSS'}`:r.endpoint||'—'}}</code><template v-else-if="key==='database'"><span class="whitespace-normal break-all" :title="connectionDatabaseLabel(r)">{{connectionDatabaseLabel(r)}}</span></template><template v-else-if="key==='environment'">{{env(r.environment)}}</template><Badge v-else-if="key==='credentials'" variant="secondary">{{kind==='connections'?(r.secret_configured?'已配置':'未配置'):r.key_path?'私钥路径':r.credential_configured?'密码（已保存）':'平台默认私钥'}}</Badge><template v-else-if="key==='connectivity'">{{testState[r.name]==='ok'?'最近测试通过':testState[r.name]==='fail'?'最近测试失败':testState[r.name]==='testing'?'测试中…':'未测试'}}</template><span v-else-if="key==='agent'" :class="agentState?.(r)?.cls">{{agentState?.(r).text||'未检测'}}</span><div v-else-if="key==='hosts'||key==='keys'" class="catalog-tags"><Badge v-for="value in (r[key]||[]).slice(0,4)" :key="value" variant="secondary">{{value}}</Badge><Badge v-if="r[key]?.length>4" variant="secondary">+{{r[key].length-4}}</Badge><span v-if="!r[key]?.length" class="muted">{{key==='hosts'?'暂无主机':'暂无变量'}}</span></div><template v-else-if="key==='created_at'||key==='updated_at'">{{fmt(r[key])}}</template><template v-else-if="key==='action'">{{auditActionLabel(r.action)}}</template><template v-else-if="key==='resource_type'">{{auditResourceLabel(r.resource_type)}}</template><template v-else>{{r[key]||'—'}}</template></template></div></TableCell><TableCell v-if="kind!=='audit'" class="align-top" :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-background':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-background':''"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:r} in [{record,rowIndex}]"><div class="catalog-actions"><Button @click="emit('edit',r)" variant="ghost" size="sm" type="button" :disabled="(busy(r))">编辑</Button><Button v-if="kind==='connections'||kind==='hosts'" @click="emit('test',r)" variant="ghost" size="sm" type="button" :disabled="(!!pending[r.name])||(testState[r.name]==='testing')"><Spinner v-if="testState[r.name]==='testing'"/>{{kind==='hosts'?'SSH 测试':'测试连接'}}</Button><Button v-if="kind==='hosts'&&showAgents" @click="emit('agent-config',r)" variant="ghost" size="sm" type="button" :disabled="(busy(r))||(pending[r.name]==='config-read')"><Spinner v-if="pending[r.name]==='config-read'"/>采集配置</Button><DropdownMenu v-if="kind==='hosts'&&showAgents"><DropdownMenuTrigger as-child><Button variant="ghost" size="sm" type="button" :disabled="(busy(r))">更多</Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem @select="emit('agent-check',r)">检测 Agent</DropdownMenuItem><DropdownMenuItem @select="emit('agent-install',r)">安装 / 升级 Agent</DropdownMenuItem><DropdownMenuItem class="catalog-danger" @select="emit('remove',r)">删除主机</DropdownMenuItem></DropdownMenuContent></DropdownMenu><Button v-else @click="emit('remove',r)" class="text-destructive" :variant="'destructive'" size="sm" type="button" :disabled="(busy(r))">删除</Button></div></template></div></TableCell></TableRow></template><TableRow v-if="!(rows||[]).length"><TableCell :colspan="2"><Empty v-if="!loading"><EmptyHeader><EmptyDescription><p>{{items.length?'没有匹配的记录':'暂无'+resourceTitles[kind]}}</p><Button v-if="items.length" @click="clear" variant="ghost" size="default" type="button">清空筛选</Button><span v-else class="muted">{{kind==='audit'?'资源配置、审批和发布操作发生后会记录在这里。':'使用右上角按钮添加，无需在每个应用重复创建。'}}</span></EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div><div class="catalog-footer"><span class="muted">{{kind==='audit'?'仅筛选最近载入的 100 条审计记录，不代表全部历史。':kind==='hosts'?'连通性与 Agent 状态仅代表最近一次检测或上报。':kind==='variables'?'这里只展示变量键，不返回或搜索密钥内容。':''}}</span><div class="flex flex-wrap items-center justify-end gap-3 py-4"><span class="mr-auto text-sm text-muted-foreground">共 {{filtered.length}} 项</span><Pagination class="mx-0 w-auto" :page="page" :total="filtered.length" :items-per-page="20" @update:page="page=$event;"><PaginationContent><PaginationPrevious/><span class="px-2 text-sm">{{page}} / {{Math.max(1,Math.ceil((filtered.length)/(20)))}}</span><PaginationNext/></PaginationContent></Pagination></div></div></template></section></template>
<style scoped>.catalog-heading,.catalog-toolbar,.catalog-actions,.catalog-footer{display:flex;align-items:center;gap:12px}.catalog-heading{justify-content:space-between;margin-bottom:16px;flex-wrap:wrap}.catalog-heading h3{font-size:1.125rem;margin:0}.catalog-toolbar{flex-wrap:wrap;margin-bottom:16px}.catalog-refresh{margin-left:auto}.catalog-actions{gap:4px;white-space:nowrap}.catalog-footer{justify-content:space-between;flex-wrap:wrap;margin-top:16px}.muted{color:var(--muted-foreground);font-size:.875rem}.catalog-tags{display:flex;gap:4px;flex-wrap:wrap;overflow-wrap:anywhere}.catalog-danger{color:var(--destructive)}@media(max-width:600px){}</style>

<style scoped>.catalog-toolbar :deep([data-slot="input-group"]){flex:1;min-width:220px;max-width:420px;width:auto}</style>
